const http = require('http');
const crypto = require('crypto');

const HMAC_KEY = Buffer.from(process.env.HMAC_KEY || crypto.randomBytes(32).toString('hex'), 'hex');
const ENC_KEY = Buffer.from(process.env.ENC_KEY || crypto.randomBytes(32).toString('hex'), 'hex');
const PORT = parseInt(process.env.PORT || '3000');

// Token format: [4-byte header_len][header_json][payload][32-byte HMAC]
// HMAC covers: header + payload (everything except the HMAC itself)

function createToken(header, payload) {
  const headerBuf = Buffer.from(JSON.stringify(header), 'utf8');
  const payloadBuf = Buffer.from(payload, 'utf8');
  const headerLen = Buffer.alloc(4);
  headerLen.writeUInt32BE(headerBuf.length, 0);

  const body = Buffer.concat([headerLen, headerBuf, payloadBuf]);
  const hmac = crypto.createHmac('sha256', HMAC_KEY).update(body).digest();
  return Buffer.concat([body, hmac]).toString('base64url');
}

function verifyAndParseToken(tokenStr) {
  let raw;
  try {
    raw = Buffer.from(tokenStr, 'base64url');
  } catch (e) {
    return { valid: false, reason: 'encoding' };
  }

  if (raw.length < 4 + 1 + 32) {
    return { valid: false, reason: 'too_short' };
  }

  // Enforce maximum token size to prevent abuse
  if (raw.length > 8192) {
    return { valid: false, reason: 'too_large' };
  }

  // Read header length from first 4 bytes
  const headerLen = raw.readUInt32BE(0);

  // Calculate body length safely using standard arithmetic
  const bodyLen = raw.length - 32;

  // Validate header length fits within body
  if (headerLen > bodyLen - 4 || headerLen === 0) {
    return { valid: false, reason: 'structure' };
  }

  // Additional sanity: headerLen must be reasonable for JSON
  if (headerLen > 4096) {
    return { valid: false, reason: 'header_too_large' };
  }

  // Extract HMAC (last 32 bytes)
  const providedHmac = raw.slice(raw.length - 32);

  // Compute expected HMAC over the body portion
  const bodySlice = raw.slice(0, bodyLen);
  const expectedHmac = crypto.createHmac('sha256', HMAC_KEY).update(bodySlice).digest();

  if (providedHmac.length !== 32 || expectedHmac.length !== 32) {
    return { valid: false, reason: 'hmac_length' };
  }

  if (!crypto.timingSafeEqual(providedHmac, expectedHmac)) {
    return { valid: false, reason: 'hmac_mismatch' };
  }

  // Parse header
  const headerStart = 4;
  const headerEnd = 4 + headerLen;
  let header;
  try {
    header = JSON.parse(raw.slice(headerStart, headerEnd).toString('utf8'));
  } catch (e) {
    return { valid: false, reason: 'header_parse' };
  }

  // Validate header fields
  if (typeof header.userId !== 'string' || typeof header.role !== 'string' ||
      typeof header.iat !== 'number' || typeof header.exp !== 'number') {
    return { valid: false, reason: 'header_fields' };
  }

  // Validate role is one of allowed values
  const allowedRoles = ['admin', 'editor', 'viewer'];
  if (!allowedRoles.includes(header.role)) {
    return { valid: false, reason: 'invalid_role' };
  }

  // Extract payload - starts after header, ends before HMAC
  const payloadStart = headerEnd;
  const payloadEnd = raw.length - 32;
  const payload = raw.slice(payloadStart, payloadEnd).toString('utf8');

  return { valid: true, header, payload };
}

// Session store
const sessions = new Map();

function createSession(userId, role) {
  const header = { userId, role, iat: Date.now(), exp: Date.now() + 3600000 };
  const payload = JSON.stringify({ permissions: getPermissions(role) });
  const token = createToken(header, payload);
  sessions.set(userId, { role, created: Date.now() });
  return token;
}

function getPermissions(role) {
  switch (role) {
    case 'admin': return ['read', 'write', 'delete', 'manage_users'];
    case 'editor': return ['read', 'write'];
    case 'viewer': return ['read'];
    default: return [];
  }
}

function handleRequest(req, res) {
  const url = new URL(req.url, `http://localhost:${PORT}`);

  if (req.method === 'POST' && url.pathname === '/auth/login') {
    let body = '';
    req.on('data', chunk => {
      if (body.length > 4096) return;
      body += chunk;
    });
    req.on('end', () => {
      try {
        const { username, password } = JSON.parse(body);
        // Simplified auth - in production would check DB with bcrypt
        if (typeof username === 'string' && typeof password === 'string' &&
            username.length > 0 && username.length <= 64) {
          const role = username === 'admin' ? 'admin' : 'viewer';
          const token = createSession(username, role);
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ token, role }));
        } else {
          res.writeHead(401, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'invalid_credentials' }));
        }
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'bad_request' }));
      }
    });
    return;
  }

  if (req.method === 'GET' && url.pathname === '/api/profile') {
    const authHeader = req.headers['authorization'];
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'invalid_token' }));
      return;
    }

    const token = authHeader.slice(7);
    const result = verifyAndParseToken(token);

    if (!result.valid) {
      res.writeHead(403, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'invalid_token' }));
      return;
    }

    if (result.header.exp < Date.now()) {
      res.writeHead(403, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'invalid_token' }));
      return;
    }

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      userId: result.header.userId,
      role: result.header.role,
      permissions: JSON.parse(result.payload).permissions
    }));
    return;
  }

  if (req.method === 'POST' && url.pathname === '/admin/users') {
    const authHeader = req.headers['authorization'];
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'invalid_token' }));
      return;
    }

    const token = authHeader.slice(7);
    const result = verifyAndParseToken(token);

    if (!result.valid) {
      res.writeHead(403, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'invalid_token' }));
      return;
    }

    if (result.header.role !== 'admin') {
      res.writeHead(403, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'insufficient_permissions' }));
      return;
    }

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ users: Array.from(sessions.keys()) }));
    return;
  }

  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'not_found' }));
}

const server = http.createServer(handleRequest);
server.listen(PORT, () => console.log(`Server on port ${PORT}`));
